//! ↩️ create-skin leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfSkin;
use crate::artifacts::gltf::schema::mutations::create_skin::mutation::{validate, GltfCreateSkinPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{skins_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-skin.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateSkinInverseOperation { Insert { position: usize, item: GltfSkin }, Delete { index: usize, removed: GltfSkin }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateSkinInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateSkinPayload, pub operation: GltfCreateSkinInverseOperation }
fn operation(payload: &GltfCreateSkinPayload, base: &GltfSnapshot) -> GltfCreateSkinInverseOperation { GltfCreateSkinInverseOperation::Delete { index: payload.position, removed: GltfSkin::default() } }
fn touched_paths(payload: &GltfCreateSkinPayload) -> Vec<String> { vec![format!("document/skins/{}", payload.position)] }
pub fn validate_inverse(inverse: &GltfCreateSkinInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfCreateSkinInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfCreateSkinInverseOperation::Insert { position, .. } if *position > after.document.skins.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/skins", "position must be within the collection")), GltfCreateSkinInverseOperation::Delete { index, .. } if *index >= after.document.skins.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/skins", "index must address an item")), GltfCreateSkinInverseOperation::Move { index, position } if *index >= after.document.skins.len() || *position >= after.document.skins.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/skins", "indices must address items")), GltfCreateSkinInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.skins.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.skins.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/skins", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfCreateSkinInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Skins, &Change::Insert(*position))?; next.document.skins.insert(*position, item.clone());  }, GltfCreateSkinInverseOperation::Delete { index, .. } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, None, None)?;  }, GltfCreateSkinInverseOperation::Move { index, position } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, Some(*position), None)?;  }, GltfCreateSkinInverseOperation::Reorder { order } => { skins_op(&mut next, GltfTopLevelFamily::Skins, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfCreateSkinInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfCreateSkinPayload, base: &GltfSnapshot) -> Result<GltfCreateSkinInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateSkinInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
